From 8378686c3eba3fdf0fe7575b096ea4b3c60b0d40 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 18:32:19 +0100
Subject: [PATCH] applets/icon: tell apart the same app installed from
 different sources

Icon widgets for one app installed from different sources looked the
same. When another widget next to it has the same name, its label and
tooltip now add where it was installed from, plus an emblem in panels.

BUG: 500735
---
 applets/icon/iconapplet.cpp | 99 +++++++++++++++++++++++++++++++++++++
 applets/icon/iconapplet.h   | 19 +++++++
 applets/icon/qml/main.qml   | 14 +++++-
 3 files changed, 131 insertions(+), 1 deletion(-)

diff --git a/applets/icon/iconapplet.cpp b/applets/icon/iconapplet.cpp
index 0142554c73..3831cceb37 100644
--- a/applets/icon/iconapplet.cpp
+++ b/applets/icon/iconapplet.cpp
@@ -6,6 +6,8 @@

 #include "iconapplet.h"

+#include <algorithm>
+
 #include <QAction>
 #include <QApplication>
 #include <QDir>
@@ -60,6 +62,11 @@ IconApplet::~IconApplet()

 void IconApplet::init()
 {
+    connect(this, &Plasma::Applet::containmentChanged, this, &IconApplet::setContainment);
+    setContainment(containment());
+    // A removed widget stays in its containment as long as its removal can be undone
+    connect(this, &Plasma::Applet::destroyedChanged, this, &IconApplet::updateShowSourceInContainment);
+
     populate();
 }

@@ -266,6 +273,23 @@ void IconApplet::populateFromDesktopFile(const QString &path)

     setIconName(desktopFile.readIcon());

+    QString sourceName;
+    QString sourceIconName;
+    if (desktopFile.desktopGroup().hasKey("X-Flatpak")) {
+        sourceName = i18nc("@info where an app was installed from", "Flatpak");
+        sourceIconName = u"application-vnd.flatpak.ref"_s;
+    } else if (desktopFile.desktopGroup().hasKey("X-SnapInstanceName")) {
+        sourceName = i18nc("@info where an app was installed from", "Snap");
+        sourceIconName = u"application-vnd.snap"_s;
+    }
+    if (m_sourceName != sourceName || m_sourceIconName != sourceIconName) {
+        m_sourceName = sourceName;
+        m_sourceIconName = sourceIconName;
+        Q_EMIT sourceChanged();
+    }
+
+    updateShowSourceInContainment();
+
     delete std::exchange(m_openContainingFolderAction, nullptr);
     m_openWithActions.clear();
     m_jumpListActions.clear();
@@ -316,6 +340,81 @@ QString IconApplet::genericName() const
     return m_genericName;
 }

+QString IconApplet::sourceName() const
+{
+    return m_sourceName;
+}
+
+QString IconApplet::sourceIconName() const
+{
+    return m_sourceIconName;
+}
+
+bool IconApplet::showSource() const
+{
+    return m_showSource;
+}
+
+void IconApplet::updateShowSourceOfIconApplets(Plasma::Containment *containment)
+{
+    if (!containment) {
+        return;
+    }
+    const auto applets = containment->applets();
+    for (Plasma::Applet *applet : applets) {
+        if (auto *iconApplet = qobject_cast<IconApplet *>(applet)) {
+            iconApplet->updateShowSource();
+        }
+    }
+}
+
+void IconApplet::setContainment(Plasma::Containment *containment)
+{
+    if (m_containment == containment) {
+        return;
+    }
+
+    Plasma::Containment *oldContainment = m_containment;
+    if (oldContainment) {
+        disconnect(oldContainment, &Plasma::Containment::appletsChanged, this, &IconApplet::updateShowSource);
+    }
+    m_containment = containment;
+    if (m_containment) {
+        connect(m_containment, &Plasma::Containment::appletsChanged, this, &IconApplet::updateShowSource);
+    }
+
+    updateShowSourceOfIconApplets(oldContainment);
+    updateShowSource();
+}
+
+// Show where the app comes from only when another Icon widget next to this one
+// shows an app with the same name installed from somewhere else
+void IconApplet::updateShowSource()
+{
+    bool showSource = false;
+    if (m_containment && !m_sourceName.isEmpty() && !destroyed()) {
+        const auto applets = m_containment->applets();
+        showSource = std::ranges::any_of(applets, [this](Plasma::Applet *applet) {
+            const auto *other = qobject_cast<IconApplet *>(applet);
+            return other && other != this && !other->destroyed() && other->m_name == m_name && other->m_sourceName != m_sourceName;
+        });
+    }
+
+    if (m_showSource != showSource) {
+        m_showSource = showSource;
+        Q_EMIT showSourceChanged();
+    }
+}
+
+void IconApplet::updateShowSourceInContainment()
+{
+    if (m_containment) {
+        updateShowSourceOfIconApplets(m_containment);
+    } else {
+        updateShowSource();
+    }
+}
+
 bool IconApplet::isValid() const
 {
     return !m_localPath.isEmpty();
